INSERT INTO sync_daily_summaries (lead_id, date, summary) VALUES
  ('efb8a8c1-cf89-4979-b018-1bf389cc3be5', '2026-10-12', $q$Nomor dikonfirmasi benar (balasan awal dari bot, lalu dari admin). Setelah pitch riset terkirim, admin membalas sore hari menanyakan keperluan kami; kami menjelaskan dari startup Sahaibat. Belum ada balasan lanjutan.$q$),
  ('acc1c1d4-65d5-427e-9034-98d492a181f2', '2026-10-12', $q$Nomor dikonfirmasi benar. Setelah pitch, pihak praktik menanyakan nama dan asal kami serta meminta tanya jawab dilakukan langsung datang ke tempat. Kami menjawab baru bisa via online dan akan mengirim link agar pihak praktik bisa menyesuaikan.$q$),
