  ('d2e7847c-7e83-46bf-aec3-51840697272b', '2026-10-12', $q$Kami menanyakan ulang ketersediaan; dijawab tidak bisa, lalu disebut sedang ada tenggat khusus. Kami akan menanyakan ulang minggu depan.$q$),
  ('8f9175e8-020b-4ee2-8d01-2d2f3dcbf011', '2026-10-12', $q$Pesan konfirmasi nomor terkirim pagi. Belum ada balasan.$q$),
